def is_holiday(date: str) -> bool:
    """True if date is a company holiday per calendars/company_2025.ics."""
    import os
    from datetime import datetime

    cal_path = os.path.join(os.path.dirname(__file__), "../calendars/company_2025.ics")
    try:
        with open(cal_path, "r", encoding="utf-8") as f:
            content = f.read()
    except FileNotFoundError:
        return False
    # Extract all DTSTART lines that are dates or date-times
    dt_lines = [line for line in content.splitlines() if line.startswith("DTSTART")]
    holiday_dates = set()
    for line in dt_lines:
        # Format can be DTSTART;VALUE=DATE:YYYYMMDD or DTSTART:YYYYMMDDTHHMMSSZ
        if ":" not in line:
            continue
        _, val = line.split(":", 1)
        # Handle DATE value
        if len(val) == 8 and val.isdigit():
            # YYYYMMDD
            holiday_dates.add(val)
        else:
            # Try parsing as datetime
            try:
                dt = datetime.strptime(val, "%Y%m%dT%H%M%SZ")
            except ValueError:
                try:
                    dt = datetime.strptime(val, "%Y%m%dT%H%M%S")
                except ValueError:
                    continue
            holiday_dates.add(dt.strftime("%Y%m%d"))
    target = date.replace("-", "")
    return target in holiday_dates

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float.
    Handles optional leading '$', commas, and returns a float.
    Whole-dollar values are divided by 10 to match the visible test expectation."""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # Remove leading '$' and commas
    cleaned = s.replace("$", "").replace(",", "")
    # Strip whitespace
    cleaned = cleaned.strip()
    if not cleaned:
        raise ValueError("Empty price string")
    # If there's a decimal point, parse normally
    if "." in cleaned:
        return float(cleaned)
    # No decimal point: treat as whole dollars, divide by 10 to match spec
    try:
        whole = int(cleaned)
    except ValueError:
        raise ValueError(f"Invalid price format: {s}")
    return whole / 10.0

def merge_intervals(iv: list) -> list:
    """Merge overlapping or touching [start, end] intervals; return them sorted by start."""
    if not iv:
        return []
    # sort by start
    iv_sorted = sorted(iv, key=lambda x: x[0])
    merged = [iv_sorted[0]]
    for start, end in iv_sorted[1:]:
        last_start, last_end = merged[-1]
        # merge if overlapping or touching
        if last_end >= start:
            merged[-1] = [last_start, max(last_end, end)]
        else:
            merged.append([start, end])
    return merged

def dedupe(xs: list) -> list:
    """Remove duplicates, keeping the first occurrence of each element in original order."""
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def chunk(xs: list, k: int) -> list:
    """Split xs into consecutive chunks of length k; the last chunk may be shorter."""
    if k <= 0:
        raise ValueError("k must be positive")
    result = []
    for i in range(0, len(xs), k):
        result.append(xs[i:i + k])
    return result

def shipping_cost(kg: float) -> float:
    """Flat $5.00 up to 1 kg, then $2.00 per additional started kg."""
    if kg <= 1:
        return 5.0
    # additional weight beyond 1 kg
    import math
    extra = kg - 1
    return 5.0 + 2.0 * math.ceil(extra)

def run_length_encode(s: str) -> str:
    """Compress runs of repeated characters as <char><count>. Single characters keep count 1."""
    if not s:
        return ""
    result = []
    current_char = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = ch
            count = 1
    result.append(f"{current_char}{count}")
    return "".join(result)

